mapper.select:
SELECT notification_id, recipient_user_id, type, title, body, read, read_at, actor_user_id, target_type, target_id, target_url, image_url, metadata_json, created_at FROM notifications WHERE recipient_user_id = #{recipientUserId}
AND read = false
AND ( created_at < #{cursorCreatedAt} OR (created_at = #{cursorCreatedAt} AND notification_id < #{cursorId}) )
ORDER BY created_at DESC, notification_id DESC LIMIT #{limit}

mapper.update:
UPDATE notifications
SET
    read = true,
    read_at = #{readAt}
WHERE notification_id = #{notificationId}
  AND recipient_user_id = #{recipientUserId}
  AND read = false

UPDATE notifications
SET
    read = true,
    read_at = #{readAt}
WHERE recipient_user_id = #{recipientUserId}
  AND read = false

UPDATE notifications
SET
    read = true,
    read_at = now()
WHERE target_id = #{conversationId}
  AND read = false AND recipient_user_id = #{userId}
